/* Monkey See, Monkey Do: service worker.
   Precaches the whole game so it opens and plays with no network.
   The PRECACHE list and VERSION are generated by `python3 scripts/build_sw.py`;
   run it after changing any game file so installed copies update. */
'use strict';

// PRECACHE-START (generated, do not edit by hand)
const VERSION = "9d0be492bef9";
const PRECACHE = [
  "./",
  "app.js",
  "manifest.webmanifest",
  "update-webview.html",
  "assets/fonts/LICENSE-baloo-2.txt",
  "assets/fonts/LICENSE-lilita-one.txt",
  "assets/fonts/baloo-2-500.woff2",
  "assets/fonts/baloo-2-700.woff2",
  "assets/fonts/lilita-one.woff2",
  "assets/icons/apple-touch-icon.png",
  "assets/icons/favicon-32.png",
  "assets/icons/icon-192.png",
  "assets/icons/icon-512.png",
  "assets/icons/icon-maskable-512.png",
  "assets/icons/icon.svg",
  "css/game.css",
  "index.html"
];
// PRECACHE-END

const CACHE = 'msmd-' + VERSION;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('msmd-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        return res;
      }).catch(() => (req.mode === 'navigate' ? caches.match('./') : Response.error()));
    })
  );
});
